/**
 * WordRam - Chechen Language Data Module (v51)
 * Authentic normative Chechen dictionary (~1500 words across A1..C2),
 * Universal grapheme tokenizer, 30 word mastery tiers, Chechen placement test.
 */

class WordRamTokenizer {
  static MULTI_GRAPHEMES_CHECHEN = ["АЬ", "ОЬ", "УЬ", "БӀ", "ГӀ", "ДӀ", "ЖӀ", "КХ", "КЪ", "КӀ", "МӀ", "ПӀ", "ТӀ", "ХЬ", "ХӀ", "ЦӀ", "ЧӀ"];
  static CYRILLIC_LETTERS_CHECHEN = new Set("АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯӀ");

  static normalizeChechen(word) {
    if (!word) return "";
    let w = String(word).trim().toUpperCase();
    w = w.replace(/[\u04CF\u04C0Il1|]/g, "\u04C0");
    w = w.replace(/ъ/g, "Ъ").replace(/ь/g, "Ь");
    return w;
  }

  static tokenizeChechen(word) {
    const w = WordRamTokenizer.normalizeChechen(word);
    const tiles = [];
    let i = 0;
    while (i < w.length) {
      if (i + 2 <= w.length && WordRamTokenizer.MULTI_GRAPHEMES_CHECHEN.includes(w.slice(i, i + 2))) {
        tiles.push(w.slice(i, i + 2));
        i += 2;
      } else if (WordRamTokenizer.CYRILLIC_LETTERS_CHECHEN.has(w[i])) {
        tiles.push(w[i]);
        i += 1;
      } else {
        if (w[i] !== " " && w[i] !== "-") {
          tiles.push(w[i]);
        }
        i += 1;
      }
    }
    return tiles;
  }

  static reconstructChechen(tiles) {
    if (!tiles || !Array.isArray(tiles)) return "";
    return tiles.join("");
  }

  static tokenizeEnglish(word) {
    if (!word) return [];
    const w = String(word).trim().toUpperCase();
    return w.split("");
  }

  static reconstructEnglish(tiles) {
    if (!tiles || !Array.isArray(tiles)) return "";
    return tiles.join("");
  }

  static tokenize(word, lang = "english") {
    if (lang === "chechen") {
      return WordRamTokenizer.tokenizeChechen(word);
    }
    return WordRamTokenizer.tokenizeEnglish(word);
  }

  static reconstruct(tiles, lang = "english") {
    if (lang === "chechen") {
      return WordRamTokenizer.reconstructChechen(tiles);
    }
    return WordRamTokenizer.reconstructEnglish(tiles);
  }

  static getTileCount(word, lang = "english") {
    return WordRamTokenizer.tokenize(word, lang).length;
  }
}

/**
 * Чеченская фонетика по графемам токенизатора.
 * ХЬ — фарингальный [ħ], не палатализованный «хь».
 * Источники соответствия: орфография Нохчийн мотт / Nichols–Komen.
 */
class ChechenPhonetics {
  static IPA_TILE = {
    "А": "a", "АЬ": "æ", "Б": "b", "БӀ": "bˤ", "В": "v", "Г": "g", "ГӀ": "ʁ",
    "Д": "d", "ДӀ": "dˤ", "Е": "e", "Ё": "jo", "Ж": "ʒ", "ЖӀ": "ʒˤ", "З": "z",
    "И": "i", "Й": "j", "К": "k", "КХ": "q", "КЪ": "qʼ", "КӀ": "kʼ",
    "Л": "l", "М": "m", "МӀ": "mˤ", "Н": "n", "О": "o", "ОЬ": "ø",
    "П": "p", "ПӀ": "pʼ", "Р": "r", "С": "s", "Т": "t", "ТӀ": "tʼ",
    "У": "u", "УЬ": "y", "Ф": "f", "Х": "χ", "ХЬ": "ħ", "ХӀ": "h",
    "Ц": "t͡s", "ЦӀ": "t͡sʼ", "Ч": "t͡ʃ", "ЧӀ": "t͡ʃʼ", "Ш": "ʃ", "Щ": "ɕː",
    "Ъ": "ʔ", "Ы": "ɨ", "Ь": "", "Э": "e", "Ю": "ju", "Я": "ja", "Ӏ": "ʕ"
  };

  static SPEAK_TILE = {
    "А": "а", "АЬ": "аэ", "Б": "б", "БӀ": "б", "В": "в", "Г": "г", "ГӀ": "гх",
    "Д": "д", "ДӀ": "д", "Е": "э", "Ё": "йо", "Ж": "ж", "ЖӀ": "ж", "З": "з",
    "И": "и", "Й": "й", "К": "к", "КХ": "кх", "КЪ": "к", "КӀ": "к",
    "Л": "л", "М": "м", "МӀ": "м", "Н": "н", "О": "о", "ОЬ": "оэ",
    "П": "п", "ПӀ": "п", "Р": "р", "С": "с", "Т": "т", "ТӀ": "т",
    "У": "у", "УЬ": "уэ", "Ф": "ф", "Х": "х", "ХЬ": "хх", "ХӀ": "х",
    "Ц": "ц", "ЦӀ": "ц", "Ч": "ч", "ЧӀ": "ч", "Ш": "ш", "Щ": "щ",
    "Ъ": "", "Ы": "ы", "Ь": "", "Э": "э", "Ю": "ю", "Я": "я", "Ӏ": ""
  };

  static POS_RU = {
    noun: "существительное",
    verb: "глагол",
    adjective: "прилагательное",
    adverb: "наречие",
    pronoun: "местоимение",
    numeral: "числительное",
    particle: "частица",
    interjection: "междометие"
  };

  static EXAMPLES = {
    "ДА": "Сан да цӀа вогӀу. — Мой отец идёт домой.",
    "НАНА": "Сан нана дика ю. — Моя мама добрая.",
    "ДАДА": "Тхан дада хьоьху. — Наш папа учит (ласк. обращение).",
    "ДЕДА": "Сан деда воккха ву. — Мой дедушка (по отцу) стар.",
    "БАБА": "Сан баба кетош ю. — Моя бабушка / мама готовит (ласк.).",
    "ДЕНАНА": "Денана кехьаш ю. — Бабушка по отцу вяжет.",
    "ВОША": "Сан воша ишколе воьду. — Мой брат идёт в школу.",
    "ЙИША": "Сан йиша книга еша. — Моя сестра читает книгу.",
    "ДОЬЗАЛ": "Тхо доьзал дукха бу. — У нас большая семья.",
    "ХЬАША": "Хьаша цӀа веана. — Гость пришёл в дом.",
    "ХӀУМА": "ХӀума хьайн ю. — Вещь твоя.",
    "ЦӀА": "ЦӀа йоьза ю. — Дом тёплый.",
    "ВАША": "Сан ваша ишколе воьду. — Мой брат идёт в школу.",
    "СО": "Со хьоьца ву. — Я с тобой.",
    "СА": "Сан са дика ду. — У меня спокойная душа.",
    "ВОН": "Иза вон хӀума ю. — Это плохая вещь.",
    "СИНТЕМ": "Цуьнна синтем беза. — Ему нужен покой.",
    "ТЕШАМ": "Ас хьуна тешам бо. — Я тебе доверяю.",
    "СОБАР": "Собар лало еза. — Нужно проявлять терпение.",
    "ДОГ": "Сан дог ирсе ду. — Моё сердце радостно.",
    "ХИ": "Хи молуш ду. — Вода холодная.",
    "БЕПИГ": "Бепиг даа. — Есть хлеб.",
    "СТАГ": "Дика стаг ву иза. — Он хороший человек.",
    "ЗУДА": "Зуда цӀа йогӀу. — Женщина идёт домой.",
    "ГӀАЛА": "Тхо гӀалахь ду. — Мы в городе.",
    "МАЛХ": "Малх кхоьссина. — Солнце взошло.",
    "БОЛХ": "Ас болх бо. — Я работаю.",
    "МАРШО": "Маршо хилийта. — Пусть будет мир.",
    "ЯХЬ": "Яхь ларъян еза. — Честь нужно беречь."
  };

  static tilesOf(word) {
    return WordRamTokenizer.tokenizeChechen(word);
  }

  static toIpa(word) {
    return this.tilesOf(word).map((t) => this.IPA_TILE[t] || t.toLowerCase()).join("");
  }

  static toSpeakable(word) {
    return this.tilesOf(word).map((t) => this.SPEAK_TILE[t] != null ? this.SPEAK_TILE[t] : t.toLowerCase()).join("");
  }

  static enrich(word, def) {
    const ipa = this.toIpa(word);
    const posRu = this.POS_RU[def.pos] || def.pos || "слово";
    const tr = def.tr || word;
    const curated = this.EXAMPLES[word] || def.ex || "";
    return {
      ph: ipa ? `[${ipa}]` : "",
      speakText: this.toSpeakable(word),
      def: `Словарное значение: ${tr}. Часть речи: ${posRu}. Уровень ${def.level || "A1"}.`,
      ex: curated
    };
  }
}

